    public Object parseMarket(Object market)
    {
        Object id = this.safeString(market, "currency_pair");
        Object name = this.safeString(market, "name");
        if (Helpers.isTrue(Helpers.isEqual(name, null)))
        {
            throw new ExchangeError((String)Helpers.add(this.id, " parseMarket() missing name")) ;
        }
        var baseIdquoteIdVariable = Helpers.split(name, "/");
        var baseId = ((java.util.List<Object>) baseIdquoteIdVariable).get(0);
        var quoteId = ((java.util.List<Object>) baseIdquoteIdVariable).get(1);
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        final Object finalBase = base;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "symbol", symbol );
            put( "base", finalBase );
            put( "quote", quote );
            put( "settle", null );
            put( "baseId", baseId );
            put( "quoteId", quoteId );
            put( "settleId", null );
            put( "type", "spot" );
            put( "spot", true );
            put( "margin", null );
            put( "swap", false );
            put( "future", false );
            put( "option", false );
            put( "active", null );
            put( "contract", false );
            put( "linear", null );
            put( "inverse", null );
            put( "contractSize", null );
            put( "expiry", null );
            put( "expiryDatetime", null );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", Zaif.this.safeNumber(market, "item_unit_step") );
                put( "price", Zaif.this.parseNumber(Zaif.this.parsePrecision(Zaif.this.safeString(market, "aux_unit_point"))) );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", Zaif.this.safeNumber(market, "item_unit_min") );
                    put( "max", null );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", Zaif.this.safeNumber(market, "aux_unit_min") );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "created", null );
            put( "info", market );
        }});
    }

    public Object parseBalance(Object response)
    {
        Object balances = this.safeValue(response, "return", new java.util.HashMap<String, Object>() {{}});
        Object deposit = this.safeValue(balances, "deposit");
        Object result = new java.util.HashMap<String, Object>() {{
            put( "info", response );
            put( "timestamp", null );
            put( "datetime", null );
        }};
        Object funds = this.safeValue(balances, "funds", new java.util.HashMap<String, Object>() {{}});
        Object currencyIds = Helpers.objectKeys(funds);
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(currencyIds)); i++)
        {
            Object currencyId = Helpers.GetValue(currencyIds, i);
            Object code = this.safeCurrencyCode(currencyId);
            Object balance = this.safeString(funds, currencyId);
            Object account = this.account();
            Helpers.addElementToObject(account, "free", balance);
            Helpers.addElementToObject(account, "total", balance);
            if (Helpers.isTrue(!Helpers.isEqual(deposit, null)))
            {
                if (Helpers.isTrue(Helpers.inOp(deposit, currencyId)))
                {
                    Helpers.addElementToObject(account, "total", this.safeString(deposit, currencyId));
                }
            }
            if (Helpers.isTrue(!Helpers.isEqual(code, null)))
            {
                Helpers.addElementToObject(result, code, account);
            }
        }
        return this.safeBalance(result);
    }

