    public Object parseTrade(Object trade, Object... optionalArgs)
    {
        //
        // fetchTrades (public)
        //
        //      {
        //          "date": 1648559414,
        //          "price": 5880375.0,
        //          "amount": 0.017,
        //          "tid": 176126557,
        //          "currency_pair": "btc_jpy",
        //          "trade_type": "ask"
        //      }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object side = this.safeString(trade, "trade_type");
        side = ((Helpers.isTrue((Helpers.isEqual(side, "bid"))))) ? "buy" : "sell";
        Object timestamp = this.safeTimestamp(trade, "date");
        Object id = this.safeString2(trade, "id", "tid");
        Object priceString = this.safeString(trade, "price");
        Object amountString = this.safeString(trade, "amount");
        Object marketId = this.safeString(trade, "currency_pair");
        Object symbol = this.safeSymbol(marketId, market, "_");
        final Object finalSide = side;
        return this.safeTrade(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "info", trade );
            put( "timestamp", timestamp );
            put( "datetime", Zaif.this.iso8601(timestamp) );
            put( "symbol", symbol );
            put( "type", null );
            put( "side", finalSide );
            put( "order", null );
            put( "takerOrMaker", null );
            put( "price", priceString );
            put( "amount", amountString );
            put( "cost", null );
            put( "fee", null );
        }}, market);
    }

